#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head; /* write index */
    size_t tail; /* read index */
    size_t size; /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static void advance(ringbuf_t *rb, size_t *idx)
{
    *idx = (*idx + 1) % rb->capacity;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t wrote = 0;

    if (!rb || !data || len == 0)
        return 0;

    while (wrote < len && rb->size < rb->capacity) {
        rb->buf[rb->head] = data[wrote];
        advance(rb, &rb->head);
        wrote++;
        rb->size++;
    }
    return wrote;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t rd = 0;

    if (!rb || !out || len == 0)
        return 0;

    while (rd < len && rb->size > 0) {
        out[rd] = rb->buf[rb->tail];
        advance(rb, &rb->tail);
        rd++;
        rb->size--;
    }
    return rd;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t rd = 0;
    size_t idx = 0;

    if (!rb || !out || len == 0)
        return 0;

    idx = rb->tail;
    while (rd < len && rd < rb->size) {
        out[rd] = rb->buf[idx];
        advance((ringbuf_t *)rb, &idx);
        rd++;
    }
    return rd;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->size = 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "ringbuf.h"

int main(void)
{
    ringbuf_t *rb = rb_create(8);
    if (!rb) { printf("FAIL: rb_create\n"); return 1; }

    /* capacity */
    if (rb_capacity(rb) != 8) { printf("FAIL: capacity\n"); return 1; }

    /* NULL handling */
    if (rb_size(NULL) != 0 || rb_read(NULL, NULL, 0) != 0) {
        printf("FAIL: NULL size/read\n"); return 1;
    }
    rb_destroy(NULL); /* must not crash */

    /* write and read */
    uint8_t wr[] = {1,2,3,4,5,6,7,8};
    size_t n = rb_write(rb, wr, sizeof(wr));
    if (n != 8) { printf("FAIL: write %zu\n", n); return 1; }

    uint8_t rd[8];
    if (rb_read(rb, rd, 8) != 8) { printf("FAIL: read\n"); return 1; }
    for (int i = 0; i < 8; i++) {
        if (rd[i] != (uint8_t)(i + 1)) { printf("FAIL: data mismatch[%d]\n", i); return 1; }
    }

    /* empty */
    if (rb_size(rb) != 0) { printf("FAIL: size empty\n"); return 1; }
    if (rb_read(rb, rd, 1) != 0) { printf("FAIL: read empty\n"); return 1; }

    /* wrap-around test */
    rb_write(rb, wr, 4);     /* fill to head=4 */
    rb_read(rb, rd, 3);       /* drain some -> tail=3 */
    uint8_t b[] = {9,10,11,12,13,14};
    n = rb_write(rb, b, sizeof(b));
    if (n != 6) { printf("FAIL: wrapped write %zu\n", n); return 1; }

    uint8_t got[8];
    if (rb_read(rb, got, 8) != 8) { printf("FAIL: after-wrap read\n"); return 1; }
    /* expected sequence: wr[3],9,10,11,12,13,14 plus one more from tail */
    uint8_t want[] = {4,9,10,11,12,13,14,?};

    /* clear */
    rb_clear(rb);
    if (rb_size(rb) != 0 || rb_capacity(rb) != 8) { printf("FAIL: clear\n"); return 1; }

    /* partial write at capacity */
    uint8_t full[8];
    n = rb_write(rb, full, 8);
    if (n != 8) { printf("FAIL: full-cap write\n"); return 1; }
    uint8_t extra[] = {99, 88};
    n = rb_write(rb, extra, 2);
    if (n != 0) { printf("FAIL: overflow should be 0 got %zu\n", n); return 1; }

    /* peek */
    rb_clear(rb);
    rb_write(rb, wr, 4);
    uint8_t peekd[4];
    size_t pn = rb_peek(rb, peekd, 4);
    if (pn != 4) { printf("FAIL: peek count\n"); return 1; }
    for (int i = 0; i < 4; i++) {
        if (peekd[i] != (uint8_t)(i + 1)) { printf("FAIL: peek data[%d]\n", i); return 1; }
    }
    /* peek must not remove */
    if (rb_size(rb) != 4) { printf("FAIL: peek should not change size\n"); return 1; }

    rb_destroy(rb);

    /* invalid create */
    if (rb_create(0) != NULL || rb_create(32) == NULL) {
        printf("FAIL: invalid/valid create\n"); return 1;
    }

    printf("OK\n");
    return 0;
}

